#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    long long x, y;
    cin >> s >> x >> y;
    // Make x <= y; then the wildcards are best as 0...0 1...1 in position order.
    if (x > y) reverse(s.begin(), s.end()), swap(x, y);
    string a = s;
    for (char &c : a)
        if (c == '!') c = '1';
    long long left0 = 0, left1 = 0, cost = 0;
    for (char c : a) {
        if (c == '0') cost += left1 * y, left0++;
        else cost += left0 * x, left1++;
    }
    long long right0 = count(a.begin(), a.end(), '0'), right1 = a.size() - right0;
    left0 = left1 = 0;
    long long best = cost;
    for (size_t i = 0; i < s.size(); i++) {
        char c = a[i];
        if (c == '0') right0--;
        else right1--;
        if (s[i] == '!') {
            // Turning this 1 into 0 changes the pairs it forms on both sides.
            cost += left1 * y - left0 * x + right1 * x - right0 * y;
            c = '0';
            best = min(best, cost);
        }
        if (c == '0') left0++;
        else left1++;
    }
    cout << best % 1000000007 << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long x = nextLong(), y = nextLong();
        // Make x <= y; then the wildcards are best as 0...0 1...1 in position order.
        if (x > y) {
            s = new StringBuilder(s).reverse().toString();
            long t = x;
            x = y;
            y = t;
        }
        char[] a = s.replace('!', '1').toCharArray();
        long left0 = 0, left1 = 0, cost = 0, right0 = 0;
        for (char c : a) {
            if (c == '0') {
                cost += left1 * y;
                left0++;
                right0++;
            } else {
                cost += left0 * x;
                left1++;
            }
        }
        long right1 = a.length - right0;
        left0 = left1 = 0;
        long best = cost;
        for (int i = 0; i < a.length; i++) {
            char c = a[i];
            if (c == '0') right0--;
            else right1--;
            if (s.charAt(i) == '!') {
                // Turning this 1 into 0 changes the pairs it forms on both sides.
                cost += left1 * y - left0 * x + right1 * x - right0 * y;
                c = '0';
                best = Math.min(best, cost);
            }
            if (c == '0') left0++;
            else left1++;
        }
        System.out.println(best % 1000000007);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := slices.Clone(nextToken())
	x, y := nextInt(), nextInt()
	// Make x <= y; then the wildcards are best as 0...0 1...1 in position order.
	if x > y {
		slices.Reverse(s)
		x, y = y, x
	}
	a := slices.Clone(s)
	var left0, left1, cost, right0 int64
	for i, c := range a {
		if c == '!' {
			a[i] = '1'
		}
		if a[i] == '0' {
			cost += left1 * y
			left0++
			right0++
		} else {
			cost += left0 * x
			left1++
		}
	}
	right1 := int64(len(a)) - right0
	left0, left1 = 0, 0
	best := cost
	for i, c := range a {
		if c == '0' {
			right0--
		} else {
			right1--
		}
		if s[i] == '!' {
			// Turning this 1 into 0 changes the pairs it forms on both sides.
			cost += left1*y - left0*x + right1*x - right0*y
			c = '0'
			best = min(best, cost)
		}
		if c == '0' {
			left0++
		} else {
			left1++
		}
	}
	fmt.Println(best % 1000000007)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
